<script>document.addEventListener('DOMContentLoaded',()=>{const trend=@json($analytics['trend']),status=@json($analytics['status']),types=@json($analytics['types']);if(typeof ApexCharts==='undefined')return;new ApexCharts(document.querySelector('#suggestion-trend'),{chart:{type:'line',height:300,toolbar:{show:false}},series:[{name:'Saran',data:trend.series.suggestion},{name:'Keluhan',data:trend.series.complaint},{name:'Improvement',data:trend.series.improvement}],xaxis:{categories:trend.labels},stroke:{curve:'smooth'},colors:['#318f8c','#ef4444','#8b5cf6'],noData:{text:'Belum ada data'}}).render();new ApexCharts(document.querySelector('#suggestion-status'),{chart:{type:'donut',height:300},series:status.map(x=>x.total),labels:status.map(x=>({submitted:'Diajukan',under_review:'Ditinjau',accepted:'Diterima',planned:'Direncanakan',in_progress:'Dikerjakan',implemented:'Diimplementasikan',rejected:'Ditolak',closed:'Ditutup'})[x.key]),legend:{position:'bottom'},noData:{text:'Belum ada data'}}).render();new ApexCharts(document.querySelector('#suggestion-types'),{chart:{type:'bar',height:260,toolbar:{show:false}},series:[{name:'Jumlah',data:types.map(x=>x.total)}],xaxis:{categories:types.map(x=>({suggestion:'Saran',complaint:'Keluhan',improvement:'Improvement'})[x.key])},colors:['#318f8c'],noData:{text:'Belum ada data'}}).render()})</script>
